SELECT r.id, r.scenario_id, s.title AS scenario_title, r.label, r.priority, r.enabled, r.created_at, r.updated_at FROM chat_recommendation r JOIN scenario s ON s.id = r.scenario_id
r.enabled = #{enabled}
ORDER BY r.priority, r.id

SELECT id, scenario_id, label, priority, enabled, created_at, updated_at
FROM chat_recommendation
WHERE id = #{id}
